    20→    private var shownIndicators: Int {
    21→        if pinsCount <= 3 {
    22→            return pinsCount
    23→        }
    24→        let maxUntruncatedIndicators = pinsCount - pinsCount % 3
    25→        if pinIndex < maxUntruncatedIndicators {
    26→            return 3
    27→        }
    28→        return pinsCount % 3
    29→    }
    30→    
    31→    var body: some View {
    32→        VStack(spacing: 2) {
    33→            ForEach(0..<3, id: \.self) { index in
    34→                Rectangle()
    35→                    .fill(index == activeIndex ? Color.compound.iconAccentPrimary : Color.compound._borderInteractiveSecondaryAlpha)
    36→                    .scaledFrame(width: 2, height: 11)
    37→                    .opacity(index < shownIndicators ? 1 : 0)
    38→            }
    39→        }
    40→    }
    41→}
