   112→enum PinnedEventsBannerState: Equatable {
   113→    case loading(numbersOfEvents: Int)
   114→    case loaded(state: PinnedEventsState)
   115→    
   116→    var isEmpty: Bool {
   117→        switch self {
   118→        case .loaded(let state):
   119→            return state.pinnedEventContents.isEmpty
   120→        case .loading(let numberOfEvents):
   121→            return numberOfEvents == 0
   122→        }
   123→    }
   124→    
   125→    var isLoading: Bool {
   126→        switch self {
   127→        case .loading:
   128→            return true
   129→        default:
   130→            return false
   131→        }
   132→    }
   133→    
   134→    var selectedPinnedEventID: String? {
   135→        switch self {
   136→        case .loaded(let state):
   137→            return state.selectedPinnedEventID
   138→        default:
   139→            return nil
   140→        }
   141→    }
   142→    
   143→    var count: Int {
   144→        switch self {
   145→        case .loaded(let state):
   146→            return state.pinnedEventContents.count
   147→        case .loading(let numberOfEvents):
   148→            return numberOfEvents
   149→        }
   150→    }
   151→    
   152→    var selectedPinnedIndex: Int {
   153→        switch self {
   154→        case .loaded(let state):
   155→            return state.selectedPinnedIndex
   156→        case .loading(let numbersOfEvents):
   157→            // We always want the index to be the last one when loading, since is the default one.
   158→            return numbersOfEvents - 1
   159→        }
   160→    }
   161→    
   162→    var displayedMessage: AttributedString {
   163→        switch self {
   164→        case .loading:
   165→            return AttributedString(L10n.screenRoomPinnedBannerLoadingDescription)
   166→        case .loaded(let state):
   167→            return state.selectedPinnedContent
   168→        }
   169→    }
   170→    
   171→    var bannerIndicatorDescription: AttributedString {
   172→        let index = selectedPinnedIndex + 1
   173→        let boldPlaceholder = "{bold}"
   174→        var finalString = AttributedString(L10n.screenRoomPinnedBannerIndicatorDescription(boldPlaceholder))
   175→        var boldString = AttributedString(L10n.screenRoomPinnedBannerIndicator(index, count))
   176→        boldString.bold()
   177→        finalString.replace(boldPlaceholder, with: boldString)
   178→        return finalString
   179→    }
   180→    
   181→    mutating func previousPin() {
   182→        switch self {
   183→        case .loaded(var state):
   184→            state.previousPin()
   185→            self = .loaded(state: state)
   186→        default:
   187→            break
   188→        }
   189→    }
   190→    
   191→    mutating func setPinnedEventContents(_ pinnedEventContents: OrderedDictionary<String, AttributedString>) {
   192→        switch self {
   193→        case .loading:
   194→            // The default selected event should always be the last one.
   195→            self = .loaded(state: .init(pinnedEventContents: pinnedEventContents, selectedPinnedEventID: pinnedEventContents.keys.last))
   196→        case .loaded(var state):
   197→            state.pinnedEventContents = pinnedEventContents
   198→            self = .loaded(state: state)
   199→        }
   200→    }
   201→    
   202→    /// Note that if we are setting this value, this is definitely sent from the pinned events timeline
   203→    /// so we can assume that the pinned events timeline is already loaded and we only need to set the
   204→    /// selection for the loaded state
   205→    mutating func setSelectedPinnedEventID(_ eventID: String) {
   206→        switch self {
   207→        case .loaded(var state):
   208→            state.selectedPinnedEventID = eventID
   209→            self = .loaded(state: state)
   210→        case .loading:
   211→            break
   212→        }
   213→    }
   214→}
   215→
   216→struct PinnedEventsState: Equatable {
   217→    var pinnedEventContents: OrderedDictionary<String, AttributedString> = [:] {
   218→        didSet {
   219→            if selectedPinnedEventID == nil, !pinnedEventContents.keys.isEmpty {
   220→                // The default selected event should always be the last one.
   221→                selectedPinnedEventID = pinnedEventContents.keys.last
   222→            } else if pinnedEventContents.isEmpty {
   223→                selectedPinnedEventID = nil
   224→            } else if let selectedPinnedEventID, !pinnedEventContents.keys.set.contains(selectedPinnedEventID) {
   225→                self.selectedPinnedEventID = pinnedEventContents.keys.last
   226→            }
   227→        }
   228→    }
   229→    
   230→    var selectedPinnedEventID: String?
   231→    
   232→    var selectedPinnedIndex: Int {
   233→        let defaultValue = pinnedEventContents.isEmpty ? 0 : pinnedEventContents.count - 1
   234→        guard let selectedPinnedEventID else {
   235→            return defaultValue
   236→        }
   237→        return pinnedEventContents.keys.firstIndex(of: selectedPinnedEventID) ?? defaultValue
   238→    }
   239→    
   240→    var selectedPinnedContent: AttributedString {
   241→        var content = AttributedString(" ")
   242→        if let selectedPinnedEventID,
   243→           let pinnedEventContent = pinnedEventContents[selectedPinnedEventID] {
   244→            content = pinnedEventContent
   245→        }
   246→        content.font = .compound.bodyMD
   247→        content.link = nil
   248→        return content
   249→    }
   250→    
   251→    mutating func previousPin() {
   252→        guard !pinnedEventContents.isEmpty else {
   253→            return
   254→        }
   255→        let currentIndex = selectedPinnedIndex
   256→        let nextIndex = currentIndex - 1
   257→        if nextIndex == -1 {
   258→            selectedPinnedEventID = pinnedEventContents.keys.last
   259→        } else {
   260→            selectedPinnedEventID = pinnedEventContents.keys[nextIndex % pinnedEventContents.count]
   261→        }
   262→    }
   263→}
