    12→struct RoomMessageEventStringBuilder {
    13→    enum Destination {
    14→        /// Strings show on the room list as the last message
    15→        /// The sender will be prefixed in bold
    16→        case roomList
    17→        /// Events pinned to the banner on the top of the timeline
    18→        /// The message type will be prefixed in bold
    19→        case pinnedEvent
    20→        /// Shown in push notifications
