    25→    let attributedStringBuilder: AttributedStringBuilderProtocol
    26→    let destination: Destination
    27→    
    28→    func buildAttributedString(for messageType: MessageType, senderDisplayName: String, isOutgoing: Bool) -> AttributedString {
    29→        let message: AttributedString
    30→        switch messageType {
    31→        case .emote(content: let content):
    32→            if let attributedMessage = attributedMessageFrom(formattedBody: content.formatted) {
    33→                return AttributedString(L10n.commonEmote(senderDisplayName, String(attributedMessage.characters)))
    34→            } else {
    35→                return AttributedString(L10n.commonEmote(senderDisplayName, content.body))
    36→            }
    37→        case .audio(content: let content):
    38→            let isVoiceMessage = content.voice != nil
    39→            var content = AttributedString(isVoiceMessage ? L10n.commonVoiceMessage : L10n.commonAudio)
    40→            if destination == .pinnedEvent {
    41→                content.bold()
    42→            }
    43→            message = content
    44→        case .image(let content):
    45→            message = buildMessage(for: destination, caption: content.caption, type: L10n.commonImage)
    46→        case .video(let content):
    47→            message = buildMessage(for: destination, caption: content.caption, type: L10n.commonVideo)
    48→        case .file(let content):
    49→            message = buildMessage(for: destination, caption: content.caption, type: L10n.commonFile)
    50→        case .location:
    51→            var content = AttributedString(L10n.commonSharedLocation)
    52→            if destination == .pinnedEvent {
    53→                content.bold()
    54→            }
    55→            message = content
    56→        case .notice(content: let content):
    57→            if let attributedMessage = attributedMessageFrom(formattedBody: content.formatted) {
    58→                message = attributedMessage
    59→            } else {
    60→                message = AttributedString(content.body)
    61→            }
    62→        case .text(content: let content):
    63→            if let attributedMessage = attributedMessageFrom(formattedBody: content.formatted) {
    64→                message = attributedMessage
    65→            } else {
    66→                message = AttributedString(content.body)
    67→            }
    68→        case .gallery(let content):
    69→            message = AttributedString(content.body)
    70→        case .other(_, let body):
    71→            message = AttributedString(body)
    72→        }
    73→
    74→        if destination == .roomList {
    75→            return prefix(message, with: isOutgoing ? L10n.commonYou : senderDisplayName)
    76→        } else {
    77→            return message
    78→        }
    79→    }
