    81→    private func buildMessage(for destination: Destination, caption: String?, type: String) -> AttributedString {
    82→        guard let caption else {
    83→            return AttributedString(type)
    84→        }
    85→        
    86→        if destination == .pinnedEvent {
    87→            return prefix(AttributedString(caption), with: type)
    88→        } else {
    89→            return AttributedString("\(type) - \(caption)")
    90→        }
    91→    }
