    96→        var attributedPrefix = AttributedString(textToBold + ":")
    97→        attributedPrefix.bold()
    98→        
    99→        // Don't include the message body in the markdown otherwise it makes tappable links.
   100→        return attributedPrefix + " " + attributedEventSummary
